<?php
namespace App\Console\Commands;
use App\Models\Booking; use Illuminate\Console\Command; use Illuminate\Support\Facades\Mail; use Illuminate\Support\Facades\Log;
class SendBookingReminders extends Command { protected $signature='bookings:send-reminders'; protected $description='Envoie les rappels e-mail des rendez-vous confirmés du lendemain'; public function handle():int { $items=Booking::with('service')->where('status','confirmed')->whereDate('appointment_date',now()->addDay()->toDateString())->whereNull('reminder_sent_at')->get(); foreach($items as $b){try{$body="Bonjour {$b->customer_name},\n\nPetit rappel : votre rendez-vous Jorsid Beauty est prévu le ".$b->appointment_date->format('d/m/Y').' à '.substr($b->appointment_time,0,5).' pour '.$b->service?->name.'. Référence : '.$b->reference.".\n\nÀ bientôt !";Mail::raw($body,fn($m)=>$m->to($b->customer_email,$b->customer_name)->subject('Rappel de votre rendez-vous — Jorsid Beauty'));$b->update(['reminder_sent_at'=>now()]);$this->info('Rappel envoyé : '.$b->reference);}catch(\Throwable $e){Log::warning('Booking reminder failed',['booking_id'=>$b->id,'error'=>$e->getMessage()]);$this->error('Échec e-mail : '.$b->reference);}}return self::SUCCESS; } }
